			// Reveal when all stylesheets are done loading.
			var waitCss = function () {
				var sheets = document.styleSheets;
				for ( var i = 0; i < sheets.length; i++ ) {
					try {
						var rules = sheets[ i ].cssRules;
						// same-origin sheet not loaded yet -> cssRules null.
						if ( rules === null ) {
